package de.kopfzentrum.gam.waitingroom;
import jakarta.annotation.PostConstruct;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.*;import java.util.*;
@Repository public class WaitingRoomVisitRepository{private final JdbcTemplate j;public WaitingRoomVisitRepository(JdbcTemplate j){this.j=j;}@PostConstruct void init(){j.execute("CREATE TABLE IF NOT EXISTS waiting_room_visit(id BIGINT AUTO_INCREMENT PRIMARY KEY,patient_number VARCHAR(80),patient_name VARCHAR(255) NOT NULL,appointment_type VARCHAR(160),practitioner VARCHAR(255),room VARCHAR(100),priority VARCHAR(30) NOT NULL DEFAULT 'NORMAL',status VARCHAR(40) NOT NULL DEFAULT 'ANGEKUENDIGT',appointment_at DATETIME,arrived_at DATETIME,called_at DATETIME,treatment_started_at DATETIME,completed_at DATETIME,next_step VARCHAR(120),note TEXT,created_by VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(255),updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_wait_status(status),INDEX idx_wait_appointment(appointment_at))");}
public List<WaitingRoomVisit> list(String q,String status){StringBuilder s=new StringBuilder("SELECT * FROM waiting_room_visit WHERE 1=1");List<Object>a=new ArrayList<>();if(q!=null&&!q.isBlank()){s.append(" AND (patient_name LIKE ? OR patient_number LIKE ? OR practitioner LIKE ? OR room LIKE ?)");for(int i=0;i<4;i++)a.add("%"+q.trim()+"%");}if(status!=null&&!status.isBlank()&&!"all".equalsIgnoreCase(status)){s.append(" AND status=?");a.add(status);}s.append(" ORDER BY CASE WHEN completed_at IS NULL THEN 0 ELSE 1 END,COALESCE(arrived_at,appointment_at),id");return j.query(s.toString(),this::map,a.toArray());}
public WaitingRoomVisit create(WaitingRoomVisitRequest r,String u){if(r.patientName()==null||r.patientName().isBlank())throw new IllegalArgumentException("Patient ist erforderlich.");j.update("INSERT INTO waiting_room_visit(patient_number,patient_name,appointment_type,practitioner,room,priority,status,appointment_at,next_step,note,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",c(r.patientNumber()),r.patientName().trim(),c(r.appointmentType()),c(r.practitioner()),c(r.room()),v(r.priority(),"NORMAL"),v(r.status(),"ANGEKUENDIGT"),dt(r.appointmentAt()),c(r.nextStep()),c(r.note()),u,u);return get(j.queryForObject("SELECT LAST_INSERT_ID()",Long.class));}
public WaitingRoomVisit transition(long id,String status,String room,String practitioner,String nextStep,String note,String u){WaitingRoomVisit x=get(id);String st=v(status,x.status());LocalDateTime now=LocalDateTime.now();j.update("UPDATE waiting_room_visit SET status=?,room=COALESCE(?,room),practitioner=COALESCE(?,practitioner),next_step=COALESCE(?,next_step),note=COALESCE(?,note),arrived_at=CASE WHEN ?='EINGETROFFEN' AND arrived_at IS NULL THEN ? ELSE arrived_at END,called_at=CASE WHEN ?='AUFGERUFEN' AND called_at IS NULL THEN ? ELSE called_at END,treatment_started_at=CASE WHEN ?='IN_BEHANDLUNG' AND treatment_started_at IS NULL THEN ? ELSE treatment_started_at END,completed_at=CASE WHEN ? IN ('ABGESCHLOSSEN','VERLASSEN','NICHT_ERSCHIENEN') THEN ? ELSE completed_at END,updated_by=? WHERE id=?",st,c(room),c(practitioner),c(nextStep),c(note),st,Timestamp.valueOf(now),st,Timestamp.valueOf(now),st,Timestamp.valueOf(now),st,Timestamp.valueOf(now),u,id);return get(id);}public void delete(long id){j.update("DELETE FROM waiting_room_visit WHERE id=?",id);}private WaitingRoomVisit get(long id){return j.query("SELECT * FROM waiting_room_visit WHERE id=?",this::map,id).stream().findFirst().orElseThrow();}
private WaitingRoomVisit map(ResultSet r,int n)throws SQLException{return new WaitingRoomVisit(r.getLong("id"),r.getString("patient_number"),r.getString("patient_name"),r.getString("appointment_type"),r.getString("practitioner"),r.getString("room"),r.getString("priority"),r.getString("status"),ldt(r,"appointment_at"),ldt(r,"arrived_at"),ldt(r,"called_at"),ldt(r,"treatment_started_at"),ldt(r,"completed_at"),r.getString("next_step"),r.getString("note"),r.getString("created_by"),ldt(r,"created_at"),r.getString("updated_by"),ldt(r,"updated_at"));}private static LocalDateTime ldt(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toLocalDateTime();}private static String c(String s){return s==null||s.isBlank()?null:s.trim();}private static String v(String s,String d){return s==null||s.isBlank()?d:s.trim().toUpperCase();}private static Timestamp dt(String s){return s==null||s.isBlank()?null:Timestamp.valueOf(LocalDateTime.parse(s));}}
